<?php
declare(strict_types=1);

/**
 * Single-file PHP + React SPA — rewrite-free routing.
 *
 * The generated index.php is completely portable and requires NO
 * rewrite rules (no .htaccess, no Nginx try_files):
 *
 *   https://example.com/index.php
 *   https://example.com/myapp/index.php
 *   https://example.com/tools/myapp/index.php
 *
 * The same file works at any mount point. Routing is done entirely
 * with query parameters, which Apache/Nginx/any server handles natively.
 *
 *   /index.php                        -> React route "/"
 *   /index.php?u=editor/123           -> React route "/editor/123"
 *   /index.php?u=settings             -> React route "/settings"
 *   /index.php?module=api&action=hello -> API
 *   /index.php?module=api&action=projects -> API
 */

const APP_NAME = 'Single PHP React SPA';

function request_method(): string
{
    return strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
}

/**
 * Read a single query parameter as a string (or the default).
 */
function request_param(string $name, ?string $default = null): ?string
{
    $value = $_GET[$name] ?? $default;

    return is_string($value) ? $value : $default;
}

function json_response(mixed $data, int $status = 200): never
{
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    header('X-Content-Type-Options: nosniff');

    echo json_encode(
        $data,
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
    );

    exit;
}

function read_json_body(): array
{
    $body = file_get_contents('php://input');

    if ($body === false || trim($body) === '') {
        return [];
    }

    $data = json_decode($body, true);

    if (!is_array($data)) {
        json_response(['error' => 'Invalid JSON body'], 400);
    }

    return $data;
}

/**
 * ------------------------------------------------------------
 * API
 *
 * Protocol:
 *   ?module=api&action=hello
 *   ?module=api&action=time
 *   ?module=api&action=projects
 * ------------------------------------------------------------
 */

function handle_api(string $action, string $method): never
{
    switch ($action) {
        case '':
        case 'index':
            json_response([
                'name' => APP_NAME,
                'status' => 'ok',
                'api' => true,
                'actions' => ['hello', 'time', 'projects'],
            ]);

        case 'hello':
            if ($method !== 'GET') {
                json_response([
                    'error' => 'Method not allowed',
                    'action' => $action,
                    'method' => $method,
                ], 405);
            }

            json_response([
                'message' => 'Hello from PHP!',
                'time' => date(DATE_ATOM),
                'route' => request_param('u', '/'),
            ]);

        case 'time':
            if ($method !== 'GET') {
                json_response([
                    'error' => 'Method not allowed',
                    'action' => $action,
                    'method' => $method,
                ], 405);
            }

            json_response([
                'unix' => time(),
                'iso' => date(DATE_ATOM),
            ]);

        case 'projects':
            if ($method === 'GET') {
                json_response([
                    ['id' => 1, 'name' => 'First project'],
                    ['id' => 2, 'name' => 'Second project'],
                ]);
            }

            if ($method === 'POST') {
                $body = read_json_body();

                if (empty($body['name']) || !is_string($body['name'])) {
                    json_response(['error' => 'name is required'], 422);
                }

                json_response([
                    'id' => random_int(1000, 9999),
                    'name' => $body['name'],
                ], 201);
            }

            json_response([
                'error' => 'Method not allowed',
                'action' => $action,
                'method' => $method,
            ], 405);

        default:
            json_response([
                'error' => 'Unknown API action',
                'action' => $action,
            ], 404);
    }
}

/**
 * ------------------------------------------------------------
 * Embedded React application
 *
 * All JavaScript and CSS are inlined into EMBEDDED_HTML at build
 * time, so index.php is the single production artifact and no asset
 * requests need rewrite rules.
 * ------------------------------------------------------------
 */

/**
 * Sanitize an SPA route into a safe, single-segment identifier used
 * only for optional <meta> tags. React receives the raw route through
 * ?u= and is responsible for lookup/404 handling.
 */
function route_title_key(string $route): string
{
    $route = trim($route, '/');

    if ($route === '') {
        return '';
    }

    $first = explode('/', $route)[0];

    if (!preg_match('/^[A-Za-z0-9_-]+$/', $first)) {
        return '';
    }

    return $first;
}

function serve_spa(string $route): never
{
    header('Content-Type: text/html; charset=utf-8');
    header('Cache-Control: no-cache');
    header('X-Content-Type-Options: nosniff');

    $html = EMBEDDED_HTML;

    /*
     * Route-aware, optional SEO/meta injection. The static <title>
     * is stripped at build time, so the route-aware one (or the app
     * default) injected here is authoritative. React still renders
     * the full client-side content.
     */
    $key = route_title_key($route);

    $meta = '<meta name="app-route" content="' .
        htmlspecialchars($route, ENT_QUOTES | ENT_HTML5, 'UTF-8') .
        '">';

    if ($key !== '') {
        $displayName = APP_NAME . ' — ' . ucfirst($key);
        $meta .= '<title>' . htmlspecialchars($displayName, ENT_QUOTES | ENT_HTML5, 'UTF-8') . '</title>';
        $meta .= '<meta name="description" content="' .
            htmlspecialchars($displayName, ENT_QUOTES | ENT_HTML5, 'UTF-8') .
            '">';
    } else {
        $meta .= '<title>' . htmlspecialchars(APP_NAME, ENT_QUOTES | ENT_HTML5, 'UTF-8') . '</title>';
    }

    $html = str_replace(
        '</head>',
        $meta . '</head>',
        $html
    );

    echo $html;
    exit;
}

